"use client";

import * as React from "react";
import styles from "../styles/beam-lines.module.css";

export interface BeamLinesProps {
  /** Number of vertical guide lines */
  lines?: number;
  /** Beam glow color */
  beamColor?: string;
  /** Speed multiplier (1 = base 2.5–4.5s per sweep) */
  speed?: number;
  /** Foreground content rendered above the beams */
  children?: React.ReactNode;
  /** Optional className merged onto the root */
  className?: string;
}

const rand = (n: number) => {
  const x = Math.sin(n * 9301 + 49297) * 233280;
  return x - Math.floor(x);
};

export function BeamLines({
  lines = 8,
  beamColor = "#38bdf8",
  speed = 1,
  children,
  className = "",
}: BeamLinesProps) {
  const safeSpeed = speed > 0 ? speed : 1;
  const total = Math.max(0, Math.round(lines));
  const styleVars = { "--mf-bl-color": beamColor } as React.CSSProperties;

  return (
    <div style={styleVars} className={`${styles.root} ${className}`.trim()}>
      <div aria-hidden="true" className={styles.field}>
        {Array.from({ length: total }, (_, i) => (
          <div key={i} className={styles.line} style={{ left: `${((i + 1) / (total + 1)) * 100}%` }}>
            <span
              className={styles.beam}
              style={{
                animationDuration: `${((2.5 + rand(i) * 2) / safeSpeed).toFixed(2)}s`,
                animationDelay: `-${(rand(i + 1) * 3).toFixed(2)}s`,
              }}
            />
          </div>
        ))}
      </div>
      <div className={styles.content}>
        {children ?? (
          <div className={styles.copy}>
            <span className={styles.eyebrow}>Signal</span>
            <h3 className={styles.title}>Beams in the grid</h3>
          </div>
        )}
      </div>
    </div>
  );
}

.root {
  position: relative;
  overflow: hidden;
  display: flex;
  width: 100%;
  min-height: 18rem;
  border-radius: 1rem;
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-bg, #09090b);
  color: var(--mf-fg, #f4f4f6);
}

.field {
  position: absolute;
  inset: 0;
  pointer-events: none;
  mask-image: linear-gradient(to bottom, transparent, black 18%, black 82%, transparent);
}

.line {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  background-color: rgba(46, 46, 56, 0.6);
}

.beam {
  position: absolute;
  inset: 0;
  animation-name: mfBeamSweep;
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  will-change: transform;
}

.beam::before {
  content: "";
  position: absolute;
  left: 0;
  top: -6rem;
  width: 1px;
  height: 6rem;
  background: linear-gradient(to bottom, transparent, var(--mf-bl-color, var(--mf-accent, #38bdf8)), transparent);
  box-shadow: 0 0 8px 0 var(--mf-bl-color, var(--mf-accent, #38bdf8));
}

.content {
  position: relative;
  z-index: 1;
  display: flex;
  flex: 1;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

.copy {
  text-align: center;
}

.eyebrow {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--mf-bl-color, var(--mf-accent, #38bdf8));
}

.title {
  margin: 0.5rem 0 0;
  padding: 0.25rem 0.75rem;
  font-size: 1.6rem;
  font-weight: 600;
  letter-spacing: -0.03em;
  background-color: rgba(9, 9, 11, 0.7);
}

@keyframes mfBeamSweep {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    transform: translate3d(0, calc(100% + 6rem), 0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .beam {
    animation: none;
    transform: translate3d(0, 55%, 0);
  }
}

