"use client";

import { motion } from "motion/react";

const rand = (n: number) => { const x = Math.sin(n * 9301 + 49297) * 233280; return x - Math.floor(x); };

export function BeamLinesTailwind({ lines = 8 }) {
  return (
    <div className="relative flex min-h-72 w-full items-center justify-center overflow-hidden rounded-2xl border border-zinc-800 bg-zinc-950">
      {Array.from({ length: lines }, (_, i) => (
        <div key={i} aria-hidden className="absolute inset-y-0 w-px bg-zinc-800/60" style={{ left: `${((i + 1) / (lines + 1)) * 100}%` }}>
          <motion.div
            className="absolute h-24 w-px bg-gradient-to-b from-transparent via-sky-400 to-transparent"
            animate={{ top: ["-25%", "120%"] }}
            transition={{ duration: 2.5 + rand(i) * 2, repeat: Infinity, delay: rand(i + 1) * 3, ease: "linear" }}
          />
        </div>
      ))}
      <h3 className="relative z-10 bg-zinc-950/70 px-3 text-2xl font-semibold text-zinc-100">Beams in the grid</h3>
    </div>
  );
}
